INSERT INTO public.dramas (title_kr, title_en, aliases, year, network, genres, status)
SELECT i.title_kr, i.title_en, i.aliases, i.year, i.network, i.genres, i.status
FROM incoming i
WHERE NOT EXISTS (
  SELECT 1 FROM public.dramas d
  WHERE lower(d.title_en)=lower(i.title_en) OR d.title_kr=i.title_kr
);